class Solution {
  public int robotSim(int[] commands, int[][] obstacles) {
    java.util.Set<Long> blocked = new java.util.HashSet<>();
    for (int[] o : obstacles) blocked.add((((long) o[0]) << 32) ^ (o[1] & 0xffffffffL));
    int[][] dirs = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
    int d = 0, x = 0, y = 0, ans = 0;
    for (int c : commands) {
      if (c == -1) d = (d + 1) % 4;
      else if (c == -2) d = (d + 3) % 4;
      else
        for (int k = 0; k < c; k++) {
          int nx = x + dirs[d][0], ny = y + dirs[d][1];
          if (blocked.contains((((long) nx) << 32) ^ (ny & 0xffffffffL))) break;
          x = nx;
          y = ny;
          ans = Math.max(ans, x * x + y * y);
        }
    }
    return ans;
  }
}
